def posMaxList(L):
    """position of the first maximum of the non empty list L"""
    p = 0
    for i in range(1, len(L)):
        if L[i] > L[p]:
            p = i
    return p

def pos_minimax(M):
    (min_i, min_j) = (0, posMaxList(M[0]))
    for i in range(1, len(M)):
        max_j = posMaxList(M[i])
        if M[i][max_j] < M[min_i][min_j]:
            (min_i, min_j) = (i, max_j)
    return (min_i, min_j)
```

