def search_matrix(M, x):
    (i, lin, col) = (0, len(M), len(M[0]))
    found = -1
    while i < lin and found == -1:
        j = 0
        while j < col and M[i][j] != x:
            j += 1
        if j != col:
            found = j
        i += 1
    if found != -1:
        return (i - 1, found)
    else:
        return (-1, -1)
```

