def init(l, c, val):
    M = []
    for i in range(l):
        L = []
        for j in range(c):
            L.append(val)
        M.append(L)
    return M

def Siamese(n):
    """n odd, n > 2"""
    S = init(n, n, 0)
    (i, j) = (n - 1, n // 2)
    for val in range(1, n * n + 1):
        S[i][j] = val
        if val % n == 0:
            i = i - 1
            if i == -1:
                i = n - 1
        else:
            (i, j) = ((i + 1) % n, (j + 1) % n)
    return S
```

