def dungeon(M):
    (l, c) = (len(M), len(M[0]))
    for j in range(1, c):
        M[0][j] += M[0][j - 1]
    for i in range(1, l):
        M[i][0] += M[i - 1][0]
    for i in range(1, l):
        for j in range(1, c):
            M[i][j] += min(M[i - 1][j], M[i][j - 1])
    return M[l - 1][c - 1] + 1
```

