Dessiner la matrice résultat de `mystery([(1, 3), (0, 0), (2, 1)])`.

```python
def mystery(L):
    res = []
    max_col = 0
    for i in range(len(L)):
        line, col = L[i]
        n = len(res)
        for j in range(n, line + 1):
            res.append([])
        nline = len(res[line])
        for j in range(nline, col + 1):
            res[line].append(-1)
        res[line][col] = i
        if col > max_col:
            max_col = col
    for i in range(len(res)):
        for j in range(len(res[i]), max_col + 1):
            res[i].append(-1)
    return res
```

