def build_symmetric(M):
    l = len(M)
    R = []
    for i in range(2 * l):
        if i < l:
            src = M[i]
        else:
            src = M[2 * l - 1 - i]
        L = []
        for j in range(len(src)):
            L.append(src[j])
        R.append(L)
    return R
```

